create table public.exercises (
 id text primary key, name text not null, name_ka text not null,
 muscle text not null check (muscle in ('chest','back','shoulders','quads','hamstrings','glutes','arms','core','cardio')),
 level text not null check (level in ('beginner','intermediate','advanced')),
 equipment text not null check (equipment in ('bodyweight','dumbbell','barbell','machine','cable','band','kettlebell')),
 cue text not null, cue_ka text not null
);
alter table public.exercises enable row level security;
revoke all on public.exercises from anon, authenticated;
grant select on public.exercises to anon, authenticated;
create policy "Anyone can read the exercise catalog" on public.exercises for select to anon, authenticated using (true);
create schema if not exists private;
create function private.valid_workout_items(items jsonb) returns boolean language plpgsql immutable set search_path = '' as $$
declare item jsonb; field text; n numeric;
begin
 if jsonb_typeof(items) is distinct from 'array' then return false; end if;
 if jsonb_array_length(items) < 1 or jsonb_array_length(items) > 40 then return false; end if;
 for item in select value from jsonb_array_elements(items) loop
  if jsonb_typeof(item) is distinct from 'object'
    or jsonb_typeof(item->'exerciseId') is distinct from 'string'
    or length(item->>'exerciseId') not between 1 and 100
    or (item->>'exerciseId') !~ '^[a-z0-9-]+$'
    or coalesce(item->>'unit','') not in ('reps','seconds') then return false; end if;
  foreach field in array array['sets','reps','rest'] loop
   if jsonb_typeof(item->field) is distinct from 'number' then return false; end if;
   n := (item->>field)::numeric;
   if n <> trunc(n) then return false; end if;
   if field = 'sets' and (n < 1 or n > 10) then return false; end if;
   if field = 'reps' and (n < 1 or n > 300) then return false; end if;
   if field = 'rest' and (n < 0 or n > 600) then return false; end if;
  end loop;
 end loop;
 return true;
end;
$$;
revoke all on schema private from public;
grant usage on schema private to authenticated;
revoke all on function private.valid_workout_items(jsonb) from public, anon;
grant execute on function private.valid_workout_items(jsonb) to authenticated;
create table public.workouts (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 name text not null check (length(btrim(name)) between 1 and 80),
 level text not null check (level in ('beginner','intermediate','advanced')),
 items jsonb not null check (private.valid_workout_items(items)),
 updated_at timestamptz not null default now(),
 created_at timestamptz not null default now()
);
create index workouts_owner_updated_idx on public.workouts (user_id, updated_at desc);
alter table public.workouts enable row level security;
revoke all on public.workouts from anon, authenticated;
grant select, insert, update, delete on public.workouts to authenticated;
create policy "Read own workouts" on public.workouts for select to authenticated using ((select auth.uid()) = user_id);
create policy "Insert own workouts" on public.workouts for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Update own workouts" on public.workouts for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "Delete own workouts" on public.workouts for delete to authenticated using ((select auth.uid()) = user_id);

